#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>
using namespace std;

// 计算单组测试数据的答案
int solveCase(int n, int m, const vector<string>& grid) {
    // 统计初始总差值：B 记为 +1，S 记为 -1
    int totalDiff = 0;
    for (int i = 0; i < n; i++) {
        for (char ch : grid[i]) {
            if (ch == 'B') {
                totalDiff++;
            } else {
                totalDiff--;
            }
        }
    }

    // 最大可能差值绝对值不超过总货位数
    int maxDiff = n * m;
    int offset = maxDiff;
    int size = 2 * maxDiff + 1;
    const int INF = 1e9;

    // dp[i] 表示当前处理到某些排后，移除部分差值为 i - offset 时的最小移除总数
    vector<int> dp(size, INF);
    dp[offset] = 0;

    // 逐排进行分组背包
    for (int i = 0; i < n; i++) {
        // 记录当前排中某个差值对应的最小移除数量
        unordered_map<int, int> best;

        // 移除长度为 0 的前缀
        int curDiff = 0;
        best[0] = 0;

        // 枚举所有前缀
        for (int j = 0; j < m; j++) {
            if (grid[i][j] == 'B') {
                curDiff++;
            } else {
                curDiff--;
            }

            int len = j + 1;

            // 相同差值只保留最小移除数量
            if (!best.count(curDiff) || len < best[curDiff]) {
                best[curDiff] = len;
            }
        }

        vector<int> ndp(size, INF);

        // 枚举旧状态
        for (int oldIdx = 0; oldIdx < size; oldIdx++) {
            if (dp[oldIdx] == INF) {
                continue;
            }

            // 枚举当前排的所有可选方案
            for (auto& entry : best) {
                int delta = entry.first;
                int cost = entry.second;
                int newIdx = oldIdx + delta;

                if (newIdx >= 0 && newIdx < size) {
                    ndp[newIdx] = min(ndp[newIdx], dp[oldIdx] + cost);
                }
            }
        }

        dp = ndp;
    }

    // 目标：移除部分差值恰好等于 totalDiff
    return dp[offset + totalDiff];
}

